{
 "summary": "The two Lean theorems state that for n ≥ 32, any division-free formula over ℂ computing per_n has at least n^4/(128·log₂ n) variable leaves. Any valid formula with division computing per_n, as an element of the fraction field, has at least n^4/(192·log₂ n) variable leaves. These match the variable-leaf parts of Theorems 1.2 and 1.3. The main caveat is coverage: the gate-count bounds G(Φ) and Theorem 1.1 (the circuit bound) are not formalized.",
 "glossary": [
  {"decl": "Formula", "line": 7, "plain": "Binary-tree arithmetic formula with leaves that are variables x_i or constants c ∈ R, and internal gates +, −, ×.", "standard_concept": "division-free arithmetic formula", "matches_standard": "yes", "note": ""},
  {"decl": "Formula.eval", "line": 18, "plain": "The polynomial in R[x_i] computed by the formula.", "standard_concept": "polynomial computed by a formula", "matches_standard": "yes", "note": ""},
  {"decl": "Formula.variableLeaves", "line": 25, "plain": "Number of variable-labelled leaves, counted with multiplicity: L_var(Φ).", "standard_concept": "L_var(Φ)", "matches_standard": "yes", "note": ""},
  {"decl": "RationalFormula", "line": 34, "plain": "Formula tree that also allows ÷ gates.", "standard_concept": "arithmetic formula with division", "matches_standard": "yes", "note": ""},
  {"decl": "RationalFormula.eval", "line": 46, "plain": "The value in the fraction field ℂ(x_ij). Division by zero gives the junk value 0, but Valid excludes it.", "standard_concept": "interpretation in the rational function field", "matches_standard": "yes", "note": ""},
  {"decl": "RationalFormula.Valid", "line": 59, "plain": "Every denominator subformula evaluates to a nonzero rational function.", "standard_concept": "valid formula with division", "matches_standard": "yes", "note": ""},
  {"decl": "RationalFormula.variableLeaves", "line": 68, "plain": "Number of variable leaves, L_var(Φ).", "standard_concept": "L_var(Φ)", "matches_standard": "yes", "note": ""},
  {"decl": "permanentPolynomial", "line": 78, "plain": "per_n = Σ_σ Π_i x_{i,σ(i)} in ℂ[x_ij].", "standard_concept": "permanent polynomial", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "permanent_divisionFree_formula_logarithmic_lower_bound", "line": 82, "plain": "For all n ≥ 32 and every division-free formula f over ℂ in the variables x_ij with eval f = per_n: n^4/(128·log₂ n) ≤ L_var(f)."},
  {"theorem": "permanent_rational_formula_logarithmic_lower_bound", "line": 90, "plain": "For all n ≥ 32 and every valid formula f with division over ℂ whose value in ℂ(x_ij) equals per_n: n^4/(192·log₂ n) ≤ L_var(f)."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "For n ≥ 2^16, C(per_n) ≥ (n²/144)(log₂log₂ n − 3)."},
  {"ref": "Theorem 1.2", "plain": "For n ≥ 32, a division-free formula Φ computing per_n has L_var ≥ n^4/(128 log₂ n) and G ≥ n^4/(256 log₂ n). The leaf bound also holds for total leaves and vertices."},
  {"ref": "Theorem 1.3", "plain": "For n ≥ 32, a valid formula with division computing per_n has L_var ≥ n^4/(192 log₂ n) and G ≥ n^4/(384 log₂ n). The leaf bound also holds for total leaves and vertices."}
 ],
 "coverage": [
