  {"paper_ref": "Theorem 1.3", "lean_theorem": "permanent_rational_formula_logarithmic_lower_bound", "relation": "lean_weaker", "why": "The L_var bound is formalized exactly; the G(Φ) bound is omitted."}
 ],
